/* ── Element spec (graph coords → world via G(x,y,z) = (y, z, x)) ────────────
   z-axis          → Line  (0,0,-0.5)→(0,0,13.2)  black 1px  + ConeGeometry arrow at top
   z ticks         → LineSegments, short screen-horizontal strokes at z=2..12, black
   x-axis          → Line  (-5,0,0)→(5,0,0)  black  + Cone arrow at +x (screen lower-left)
   x ticks         → LineSegments perpendicular in xy-plane at x=±2,±4
   y-axis          → Line  (0,-5,0)→(0,5,0)  black  + Cone arrow at +y (screen lower-right)
   y ticks         → LineSegments perpendicular in xy-plane at y=±2,±4
   helix (ghost)   → THREE.Line, 801 sampled points, navy #1f4e79
   helix (trace)   → THREE.Line, same samples, drawRange 0..idx(t), navy, on top
   direction arrows→ 2 × ConeGeometry tangent to curve at t≈1.2 and t≈6.0, navy
   moving point    → SphereGeometry(0.25) #c0392b
   radial guide    → Line (0,0,z)→P(t), light grey 45%
   drop line       → Line (dashed) P(t)→(x,y,0), light grey 45%
   all text        → addLabel (HTML overlays)
──────────────────────────────────────────────────────────────────────────── */

const NAVY = 0x1f4e79;
const BLACK = 0x111111;
const GREY = 0x9aa0a6;
const T0 = 0, T1 = 12.8, NS = 801;

// graph (x,y,z) → world (y, z, x): puts graph +x to screen lower-left,
// graph +y to screen lower-right, graph +z straight up, in the iso pose.
const G = (x, y, z) => new THREE.Vector3(y, z, x);

function mkLine(a, b, color, opacity) {
  const g = new THREE.BufferGeometry().setFromPoints([a, b]);
  const m = new THREE.LineBasicMaterial({ color, transparent: opacity !== undefined, opacity: opacity ?? 1 });
  return new THREE.Line(g, m);
}
function mkSegs(pts, color) {
  const g = new THREE.BufferGeometry().setFromPoints(pts);
  return new THREE.LineSegments(g, new THREE.LineBasicMaterial({ color }));
}
function mkCone(pos, dir, color, r, h) {
  const mesh = new THREE.Mesh(new THREE.ConeGeometry(r, h, 20),
    new THREE.MeshBasicMaterial({ color }));
  mesh.position.copy(pos);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return mesh;
}

/* ── Axes ─────────────────────────────────────────────────────────────── */
const axes = new THREE.Group();
scene.add(axes);

axes.add(mkLine(G(0, 0, -0.5), G(0, 0, 13.2), BLACK));
axes.add(mkCone(G(0, 0, 13.42), new THREE.Vector3(0, 1, 0), BLACK, 0.16, 0.45));

axes.add(mkLine(G(-5, 0, 0), G(5, 0, 0), BLACK));
axes.add(mkCone(G(5.2, 0, 0), G(1, 0, 0).sub(G(0, 0, 0)), BLACK, 0.16, 0.45));

axes.add(mkLine(G(0, -5, 0), G(0, 5, 0), BLACK));
axes.add(mkCone(G(0, 5.2, 0), G(0, 1, 0).sub(G(0, 0, 0)), BLACK, 0.16, 0.45));

// ticks
const tickPts = [];
[-4, -2, 2, 4].forEach(v => {
  tickPts.push(G(v, -0.18, 0), G(v, 0.18, 0));   // on x-axis
  tickPts.push(G(-0.18, v, 0), G(0.18, v, 0));   // on y-axis
});
const zTicks = [];
for (let k = 2; k <= 12; k += 2) {
  zTicks.push(G(-0.16, 0.16, k), G(0.16, -0.16, k)); // screen-horizontal stroke
}
axes.add(mkSegs(tickPts, BLACK));
const zTickObj = mkSegs(zTicks, BLACK);
axes.add(zTickObj);

/* ── Curve (ghost + trace) ────────────────────────────────────────────── */
const posGhost = new Float32Array(NS * 3);
const posTrace = new Float32Array(NS * 3);
const ghostGeom = new THREE.BufferGeometry();
ghostGeom.setAttribute('position', new THREE.BufferAttribute(posGhost, 3));
const traceGeom = new THREE.BufferGeometry();
traceGeom.setAttribute('position', new THREE.BufferAttribute(posTrace, 3));

const ghostMat = new THREE.LineBasicMaterial({ color: NAVY, transparent: true, opacity: 1 });
const ghostLine = new THREE.Line(ghostGeom, ghostMat);
const traceLine = new THREE.Line(traceGeom, new THREE.LineBasicMaterial({ color: NAVY }));
traceLine.renderOrder = 2;
scene.add(ghostLine, traceLine);

registerInteractive(ghostLine, {
  title: 'The helix r(t) = 4cos t i + 4sin t j + t k',
  tooltip: 'Space curve r(t)',
  body: 'Every value of t gives one position vector. The i and j components trace a circle of radius 4 in the xy-plane; the k component rises linearly, so the trail is a spring-shaped helix. Over t ∈ [0, 12.8] it makes about two full turns and reaches just past z = 12.'
});

/* ── Direction arrowheads on the curve ────────────────────────────────── */
const dirArrows = [1.2, 6.0].map(() => {
  const m = new THREE.Mesh(new THREE.ConeGeometry(0.22, 0.62, 18),
    new THREE.MeshBasicMaterial({ color: NAVY }));
  scene.add(m);
  return m;
});

/* ── Moving point + guides ────────────────────────────────────────────── */
const marker = new THREE.Mesh(new THREE.SphereGeometry(0.25, 20, 16),
  new THREE.MeshBasicMaterial({ color: 0xc0392b }));
marker.renderOrder = 3;
scene.add(marker);
registerInteractive(marker, {
  title: 'The point r(t)',
  tooltip: 'Current position r(t)',
  body: 'This is the tip of the position vector at the current parameter value t. Its distance from the z-axis stays 4 while its height equals t.'
});

