scene.add(radial);

const dropGeom = new THREE.BufferGeometry().setFromPoints([G(0, 0, 0), G(0, 0, 0)]);
const dropLine = new THREE.Line(dropGeom, new THREE.LineDashedMaterial({
  color: GREY, dashSize: 0.28, gapSize: 0.22, transparent: true, opacity: 0.7
}));
