/* ── Sampling from the compiled component functions ───────────────────── */
const F = {
  x: compileExpr('4*cos(t)', ['t']),
  y: compileExpr('4*sin(t)', ['t']),
  z: compileExpr('t', ['t'])
};
const SRC = { x: '4*cos(t)', y: '4*sin(t)', z: 't' };

function clampv(v, last) {
  if (!Number.isFinite(v)) return last;
  return Math.max(-30, Math.min(30, v));
}
function P(t) {
  const x = clampv(F.x(t), 0), y = clampv(F.y(t), 0), z = clampv(F.z(t), 0);
  return G(x, y, z);
}

function rebuildCurve() {
  let lx = 0, ly = 0, lz = 0;
  for (let i = 0; i < NS; i++) {
    const t = T0 + (T1 - T0) * i / (NS - 1);
    const x = clampv(F.x(t), lx), y = clampv(F.y(t), ly), z = clampv(F.z(t), lz);
    lx = x; ly = y; lz = z;
    posGhost[3 * i] = y; posGhost[3 * i + 1] = z; posGhost[3 * i + 2] = x;
    posTrace[3 * i] = y; posTrace[3 * i + 1] = z; posTrace[3 * i + 2] = x;
  }
  ghostGeom.attributes.position.needsUpdate = true;
  traceGeom.attributes.position.needsUpdate = true;
  ghostGeom.computeBoundingSphere();
  traceGeom.computeBoundingSphere();

  // direction arrowheads tangent to the curve
  [1.2, 6.0].forEach((ta, k) => {
    const a = P(Math.max(T0, ta - 0.06)), b = P(Math.min(T1, ta + 0.06));
    const dir = b.clone().sub(a);
    if (dir.lengthSq() < 1e-8) { dirArrows[k].visible = false; return; }
    dirArrows[k].visible = true;
    dirArrows[k].position.copy(P(ta));
    dirArrows[k].quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  });
  updateEqLabel();
}

/* ── t state ──────────────────────────────────────────────────────────── */
let tCur = 0;
const slider = document.getElementById('tParam');
const tValEl = document.getElementById('tVal');
