    'x = ' + clampv(F.x(tCur), 0).toFixed(2) +
    '<br>y = ' + clampv(F.y(tCur), 0).toFixed(2) +
    '<br>z = ' + clampv(F.z(tCur), 0).toFixed(2);
}

