const STEPS = [
  { title: 'The curve and its axes', n: 'A single dark-blue space curve winds twice around the vertical z-axis, reaching just past z = 12. The x-axis recedes to the lower left, the y-axis to the lower right.', view: '3D view', t: 0 },
  { title: 'One quarter turn', n: 'At t = π/2 the point sits at (0, 4, π/2): x has dropped to 0, y has risen to its maximum 4, and the height equals t.', view: '3D view', t: 1.571 },
