// @FIGURE_CODE_BEGIN
/* ── Element spec (graph coords → world via G(x,y,z) = (y,z,x)·S, S = 0.25) ──
   z-axis            → Line (0,0,-0.5)→(0,0,14.0) black 1px + ConeGeometry arrow @14.25
   z ticks           → LineSegments, short screen-horizontal strokes at z = 2,4,…,12
   x-axis            → Line (-5.2,0,0)→(5.0,0,0) black + Cone arrow at +x (screen lower-left)
   x ticks           → LineSegments along y at x = ±2, ±4
   y-axis            → Line (0,-5.2,0)→(0,5.0,0) black + Cone arrow at +y (screen lower-right)
   y ticks           → LineSegments along x at y = ±2, ±4
   helix (ghost)     → TubeGeometry over 801 sampled pts, navy #1f4e79, r ≈ 0.055 graph
   helix (trace)     → identical tube, index drawRange 0…arc-fraction(t), navy, on top
   direction arrows  → 2 × ConeGeometry tangent to curve at t ≈ 1.5 (z≈1.5) and t ≈ 6.0
   moving point      → SphereGeometry(0.25 graph) #c0392b   (hidden until t is used)
   radial guide      → Line (0,0,z)→P(t) light grey        (hidden until t is used)
   drop line         → dashed Line P(t)→(x,y,0) light grey  (hidden until t is used)
   all text          → addLabel HTML overlays (numerals 14px, axis letters bold 16px,
                       equation bold 16px, upper right)
──────────────────────────────────────────────────────────────────────────── */

const S = 0.25;                       // world units per graph unit
const NAVY = 0x1f4e79;
const BLACK = 0x111111;
const GREY = 0x9aa0a6;
const RED = 0xc0392b;
const T0 = 0, T1 = 12.8, NS = 801;
const TUBULAR = 600, RADIAL = 8, TUBE_R = 0.055 * S;

// graph (x,y,z) → world (y,z,x)·S : graph +x to screen lower-left,
// graph +y to screen lower-right, graph +z straight up (isometric pose).
const G = (x, y, z) => new THREE.Vector3(y * S, z * S, x * S);

let eqLabel = null;          // declared early: rebuildCurve() touches it
let tTween = null;
let camTween = null;
let revealed = false;
let viewMode = '3D view';

function mkLine(a, b, color, opacity) {
  const g = new THREE.BufferGeometry().setFromPoints([a, b]);
  const m = new THREE.LineBasicMaterial({
    color, transparent: opacity !== undefined, opacity: opacity === undefined ? 1 : opacity
  });
  return new THREE.Line(g, m);
}
function mkSegs(pts, color) {
  return new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color }));
}
function mkCone(pos, dir, color, rG, hG) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(rG * S, hG * S, 20),
    new THREE.MeshBasicMaterial({ color }));
  m.position.copy(pos);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return m;
}

/* ── Axes ─────────────────────────────────────────────────────────────── */
const axes = new THREE.Group();
scene.add(axes);

// z-axis: extends well above the top of the helix (z = 12.8)
axes.add(mkLine(G(0, 0, -0.5), G(0, 0, 14.0), BLACK));
axes.add(mkCone(G(0, 0, 14.25), new THREE.Vector3(0, 1, 0), BLACK, 0.18, 0.5));

// x-axis (positive end toward screen lower-left)
axes.add(mkLine(G(-5.2, 0, 0), G(5.0, 0, 0), BLACK));
axes.add(mkCone(G(5.25, 0, 0), new THREE.Vector3(0, 0, 1), BLACK, 0.18, 0.5));

// y-axis (positive end toward screen lower-right)
axes.add(mkLine(G(0, -5.2, 0), G(0, 5.0, 0), BLACK));
axes.add(mkCone(G(0, 5.25, 0), new THREE.Vector3(1, 0, 0), BLACK, 0.18, 0.5));

// ticks on the horizontal axes (perpendicular strokes in the xy-plane)
const tickPts = [];
[-4, -2, 2, 4].forEach(v => {
  tickPts.push(G(v, -0.22, 0), G(v, 0.22, 0));
  tickPts.push(G(-0.22, v, 0), G(0.22, v, 0));
});
axes.add(mkSegs(tickPts, BLACK));

// ticks on the z-axis (short screen-horizontal strokes)
const zTickPts = [];
for (let k = 2; k <= 12; k += 2) zTickPts.push(G(-0.2, 0.2, k), G(0.2, -0.2, k));
const zTickObj = mkSegs(zTickPts, BLACK);
axes.add(zTickObj);

/* ── Curve: ghost tube + traced tube ──────────────────────────────────── */
const ghostMat = new THREE.MeshBasicMaterial({ color: NAVY, transparent: true, opacity: 1 });
const traceMat = new THREE.MeshBasicMaterial({ color: NAVY });
const ghostMesh = new THREE.Mesh(new THREE.BufferGeometry(), ghostMat);
const traceMesh = new THREE.Mesh(new THREE.BufferGeometry(), traceMat);
traceMesh.renderOrder = 2;
scene.add(ghostMesh, traceMesh);

registerInteractive(ghostMesh, {
  title: 'The helix r(t) = 4cos t i + 4sin t j + t k',
  tooltip: 'Space curve r(t)',
  body: 'Every value of t gives one position vector. The i and j components trace a circle of radius 4 in the xy-plane; the k component rises linearly with t, so the trail is a spring-shaped helix. Over t ∈ [0, 12.8] it makes about two full turns and climbs just past z = 12.'
});

/* ── Direction arrowheads on the curve ────────────────────────────────── */
const ARROW_TS = [1.5, 6.0];
const dirArrows = ARROW_TS.map(() => {
  const m = new THREE.Mesh(new THREE.ConeGeometry(0.3 * S, 0.85 * S, 18),
    new THREE.MeshBasicMaterial({ color: NAVY }));
  m.renderOrder = 3;
  scene.add(m);
  return m;
});

/* ── Moving point + guides (hidden until t is used) ───────────────────── */
const marker = new THREE.Mesh(new THREE.SphereGeometry(0.25 * S, 20, 16),
  new THREE.MeshBasicMaterial({ color: RED }));
marker.renderOrder = 4;
scene.add(marker);
registerInteractive(marker, {
  title: 'The point r(t)',
  tooltip: 'Current position r(t)',
  body: 'The tip of the position vector at the current parameter value t. For the helix its distance from the z-axis stays 4 while its height equals t.'
});

const radial = mkLine(G(0, 0, 0), G(4, 0, 0), GREY, 0.55);
scene.add(radial);

const dropLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([G(0, 0, 0), G(0, 0, 0)]),
  new THREE.LineDashedMaterial({
    color: GREY, dashSize: 0.3 * S, gapSize: 0.24 * S, transparent: true, opacity: 0.7
  })
);
scene.add(dropLine);

/* ── Compiled component functions (everything is sampled from these) ──── */
const F = {
  x: compileExpr('4*cos(t)', ['t']),
  y: compileExpr('4*sin(t)', ['t']),
  z: compileExpr('t', ['t'])
};
const SRC = { x: '4*cos(t)', y: '4*sin(t)', z: 't' };

function clampv(v, last) {
  if (!Number.isFinite(v)) return last;
  return Math.max(-40, Math.min(40, v));
}
function P(t) {
  return G(clampv(F.x(t), 0), clampv(F.y(t), 0), clampv(F.z(t), 0));
}

let cumArc = [0], totalArc = 1;

function rebuildCurve() {
  const pts = [];
  let lx = 0, ly = 0, lz = 0;
  for (let i = 0; i < NS; i++) {
    const t = T0 + (T1 - T0) * i / (NS - 1);
    const x = clampv(F.x(t), lx), y = clampv(F.y(t), ly), z = clampv(F.z(t), lz);
    lx = x; ly = y; lz = z;
    pts.push(new THREE.Vector3(y * S, z * S, x * S));
  }
  cumArc = [0];
  let L = 0;
  for (let i = 1; i < NS; i++) { L += pts[i].distanceTo(pts[i - 1]); cumArc.push(L); }
  totalArc = L;

  if (!(L > 1e-4)) {                      // degenerate (constant) curve
    ghostMesh.visible = false;
    traceMesh.visible = false;
    dirArrows.forEach(a => { a.visible = false; });
    updateEqLabel();
    return;
  }
  ghostMesh.visible = true;
  traceMesh.visible = true;

  const curve = new THREE.CatmullRomCurve3(pts);
  curve.arcLengthDivisions = 800;
  const g1 = new THREE.TubeGeometry(curve, TUBULAR, TUBE_R * 0.96, RADIAL, false);
  const g2 = new THREE.TubeGeometry(curve, TUBULAR, TUBE_R, RADIAL, false);
  ghostMesh.geometry.dispose(); ghostMesh.geometry = g1;
  traceMesh.geometry.dispose(); traceMesh.geometry = g2;

  // tangent arrowheads on the ascending curve
  ARROW_TS.forEach((ta, k) => {
    const a = P(Math.max(T0, ta - 0.05)), b = P(Math.min(T1, ta + 0.05));
    const dir = b.clone().sub(a);
    if (dir.lengthSq() < 1e-10) { dirArrows[k].visible = false; return; }
    dirArrows[k].visible = true;
    dirArrows[k].position.copy(P(ta));
    dirArrows[k].quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  });
  updateEqLabel();
}

/* ── t state ──────────────────────────────────────────────────────────── */
let tCur = 0;
const slider = document.getElementById('tParam');
const tValEl = document.getElementById('tVal');
const readoutEl = document.getElementById('readout');

function updateTraceRange() {
  if (!revealed) { traceMesh.geometry.setDrawRange(0, 0); return; }
  const idx = Math.round((tCur - T0) / (T1 - T0) * (NS - 1));
  const frac = totalArc > 0 ? cumArc[Math.max(0, Math.min(NS - 1, idx))] / totalArc : 0;
  const segs = Math.max(1, Math.round(frac * TUBULAR));
  traceMesh.geometry.setDrawRange(0, segs * RADIAL * 6);
}

function setReveal(on) {
  revealed = on;
  marker.visible = on;
  radial.visible = on;
  dropLine.visible = on;
  ghostMat.opacity = on ? 0.25 : 1.0;
  updateTraceRange();
}

function setT(t, syncSlider = true) {
  tCur = Math.max(T0, Math.min(T1, t));
  const p = P(tCur);
  marker.position.copy(p);
  const base = G(0, 0, clampv(F.z(tCur), 0));
  radial.geometry.setFromPoints([base, p]);
  const foot = G(clampv(F.x(tCur), 0), clampv(F.y(tCur), 0), 0);
  dropLine.geometry.setFromPoints([p, foot]);
  dropLine.computeLineDistances();
  updateTraceRange();

  if (syncSlider) slider.value = tCur.toFixed(2);
  tValEl.textContent = tCur.toFixed(2);
  readoutEl.innerHTML =
    'x = ' + clampv(F.x(tCur), 0).toFixed(2) +
    '<br>y = ' + clampv(F.y(tCur), 0).toFixed(2) +
    '<br>z = ' + clampv(F.z(tCur), 0).toFixed(2);
}

rebuildCurve();
setT(0);
setReveal(false);

/* ── Camera ───────────────────────────────────────────────────────────── */
const ISO_ELEV = 35.264389682754654;
function applyCam(elevDeg) {
  setCameraView({
    projection: 'orthographic',
    azimuthDeg: 45,
    elevationDeg: elevDeg,
    rollDeg: 0,
    heightFraction: 0.84
  });
}
applyCam(ISO_ELEV);

/* ── Labels ───────────────────────────────────────────────────────────── */
const NUM = { fontSize: '14px' };
const zLabelEntries = [];
for (let k = 2; k <= 12; k += 2) {
  zLabelEntries.push(addLabel(String(k), G(0, 0, k), { offset: [-21, 0], fontSize: '14px' }));
}
zLabelEntries.push(addLabel('<b><i>z</i></b>', G(0, 0, 15.0),
