/* ── Equation inputs (all geometry is resampled from the compiled fns) ── */
function refit() { applyCam(viewMode === '3D view' ? ISO_ELEV : 88); }
bindEquationInput('xt', (fn, src) => { F.x = fn; SRC.x = src; rebuildCurve(); setT(tCur); refit(); }, { variables: ['t'] });
bindEquationInput('yt', (fn, src) => { F.y = fn; SRC.y = src; rebuildCurve(); setT(tCur); refit(); }, { variables: ['t'] });
bindEquationInput('zt', (fn, src) => { F.z = fn; SRC.z = src; rebuildCurve(); setT(tCur); refit(); }, { variables: ['t'] });

document.getElementById('btnEqReset').addEventListener('click', () => {
