    el.value = defs[id];
    el.dispatchEvent(new Event('input'));
  });
});

/* ── Play / pause ─────────────────────────────────────────────────────── */
let playing = false;
const btnTrace = document.getElementById('btnTrace');
function setPlaying(on) {
  playing = on;
  btnTrace.textContent = on ? '❚❚ Pause trace' : '▶ Trace r(t)';
  btnTrace.classList.toggle('active', on);
  if (on) setReveal(true);
}
btnTrace.addEventListener('click', () => {
  if (!playing && tCur >= T1 - 1e-6) setT(T0);
  setPlaying(!playing);
});
slider.addEventListener('input', () => {
  setPlaying(false);
  tTween = null;
  setReveal(true);
  setT(parseFloat(slider.value), false);
});

/* ── View toggle ──────────────────────────────────────────────────────── */
const btn3D = document.getElementById('btnView3D');
const btnTop = document.getElementById('btnViewTop');
function setView(mode) {
  viewMode = mode;
  btn3D.classList.toggle('active', mode === '3D view');
  btnTop.classList.toggle('active', mode !== '3D view');
  const to = mode === '3D view' ? ISO_ELEV : 88;
  const from = window.__figureCameraView ? window.__figureCameraView.elevationDeg : ISO_ELEV;
  camTween = { from, to, p: 0, dur: 0.6 };
  const fade = mode === '3D view' ? 1 : 0.15;
  zLabelEntries.forEach(e => { e.div.style.opacity = fade; });
  zTickObj.visible = mode === '3D view';
}
btn3D.addEventListener('click', () => setView('3D view'));
btnTop.addEventListener('click', () => setView('Top view (xy-plane)'));
document.getElementById('btnResetView').addEventListener('click', () => {
  camTween = null;
  applyCam(viewMode === '3D view' ? ISO_ELEV : 88);
});

/* ── Demo steps ───────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'The curve and its axes', n: 'A single dark-blue space curve winds twice around the vertical z-axis, reaching just past z = 12. The x-axis recedes to the lower left, the y-axis to the lower right.', view: '3D view', t: 0, reveal: false },
  { title: 'One quarter turn', n: 'At t = π/2 the point sits at (0, 4, π/2): x has dropped to 0, y has risen to its maximum 4, and the height equals t.', view: '3D view', t: 1.571, reveal: true },
  { title: 'One full loop, height 2π', n: 'After t = 2π the point is back over its starting direction (4, 0) but has climbed to z = 2π ≈ 6.28 — the horizontal motion repeats, the vertical motion does not.', view: '3D view', t: 6.283, reveal: true },
  { title: 'Look straight down', n: 'From above, both loops land on the same circle of radius 4: the horizontal motion is exactly 4cos t i + 4sin t j.', view: 'Top view (xy-plane)', t: 6.283, reveal: true },
  { title: 'Play the motion', n: 'Back in 3D, let the point run: constant circling plus constant rise traces the full helix to just above z = 12.', view: '3D view', t: 12.8, reveal: true }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  setPlaying(false);
  if (s.view !== viewMode) setView(s.view);
  setReveal(s.reveal);
  if (s.reveal) tTween = { from: tCur, to: s.t, p: 0, dur: 0.8 };
  else { tTween = null; setT(s.t); }
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepNarr').textContent = s.n;
  document.getElementById('stepNum').textContent = (stepIdx + 1) + ' / ' + STEPS.length;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(0);

/* ── Driver loop ──────────────────────────────────────────────────────── */
let _last = performance.now();
function driver(now) {
  requestAnimationFrame(driver);
  const dt = Math.min(0.05, (now - _last) / 1000);
  _last = now;

  if (camTween) {
    camTween.p += dt / camTween.dur;
    const k = Math.min(1, camTween.p);
    const e = k * k * (3 - 2 * k);
    applyCam(camTween.from + (camTween.to - camTween.from) * e);
    if (k >= 1) camTween = null;
  }

  if (tTween) {
    tTween.p += dt / tTween.dur;
    const k = Math.min(1, tTween.p);
    const e = k * k * (3 - 2 * k);
    setT(tTween.from + (tTween.to - tTween.from) * e);
    if (k >= 1) tTween = null;
  } else if (playing) {
    let t = tCur + dt * 2.0;
    if (t > T1) t = T0;
    setT(t);
  }
}
requestAnimationFrame(driver);
